#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1, y1, x2, y2, x3, y3;
    cout << "Введіть координати x1 y1 x2 y2 x3 y3: ";
    cin >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;

    // сторони — відстані між вершинами
    double a = sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
    double b = sqrt(pow(x3 - x2, 2) + pow(y3 - y2, 2));
    double c = sqrt(pow(x1 - x3, 2) + pow(y1 - y3, 2));

    double P = a + b + c;                              // периметр
    double p = P / 2;                                  // півпериметр
    double S = sqrt(p * (p - a) * (p - b) * (p - c));  // формула Герона

    cout << "P = " << P << endl;
    cout << "S = " << S << endl;
    return 0;
}
